           <h1>Notification preferences</h1>
           <p class="intro">
             Choose the channel you want us to use for important account and
             product updates.
           </p>
           <form id="notification-form" novalidate>
             <div class="form-field">
               <fieldset>
                 <legend>
                   How do you prefer to receive notifications?
                   <span class="required-note" aria-hidden="true">*</span>
                 </legend>
                 <p class="hint" id="notification-hint">
                   Required. Select one option.
                 </p>
                 <div class="options">
                   ${optionMarkup}
                 </div>
                 <p class="error-message" id="notification-error" data-visible="false">
                   Select Email, SMS, or Push Notifications before submitting.
                 </p>
               </fieldset>
             </div>
             <button class="submit-button" type="submit">Submit preference</button>
             <p class="status" id="form-status" aria-live="polite"></p>
           </form>
         `;
       }

       function App() {
         return NotificationPreferenceForm();
       }

       function setRadioInvalidState(isInvalid) {
         document
           .querySelectorAll('input[name="notification-preference"]')
           .forEach((radio) => {
             radio.setAttribute("aria-invalid", String(isInvalid));
           });
       }

       document.querySelector("#app").innerHTML = App();

       const form = document.querySelector("#notification-form");
       const error = document.querySelector("#notification-error");
       const status = document.querySelector("#form-status");

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         const selected = form.querySelector(
           'input[name="notification-preference"]:checked'
         );

         if (!selected) {
           error.dataset.visible = "true";
           setRadioInvalidState(true);
           status.textContent = "";
           form.querySelector('input[name="notification-preference"]').focus();
           return;
         }

         error.dataset.visible = "false";
         setRadioInvalidState(false);
         const selectedLabel = notificationOptions.find(
           (option) => option.value === selected.value
         ).label;
         status.textContent = `Preference saved: ${selectedLabel}.`;
       });

       form.addEventListener("change", () => {
         error.dataset.visible = "false";
         setRadioInvalidState(false);
       });
     </script>
   </body>
 </html>

')
